    { const char * tb_v1269 = "// --- ошибки процессора ---\n"; *(const char * *)tb_grow(v_lines) = tb_v1269; }
    { const char * tb_v1270 = "TB_API const char *tb_fault_name[32] = {\"деление на ноль\", \"отладка\", \"NMI\", \"точка останова\", \"переполнение\",\n"; *(const char * *)tb_grow(v_lines) = tb_v1270; }
    { const char * tb_v1271 = "    \"выход за границы\", \"неизвестная команда\", \"нет FPU\", \"двойная ошибка\", \"\", \"плохой TSS\", \"нет сегмента\",\n"; *(const char * *)tb_grow(v_lines) = tb_v1271; }
    { const char * tb_v1272 = "    \"ошибка стека\", \"нарушение защиты\", \"ошибка страницы\", \"\", \"ошибка дробей\", \"выравнивание\", \"проверка железа\", \"ошибка SIMD\"};\n"; *(const char * *)tb_grow(v_lines) = tb_v1272; }
    { const char * tb_v1273 = "// клетка (задача background) упала: только она и заканчивается, ядро и другие клетки живут.\n"; *(const char * *)tb_grow(v_lines) = tb_v1273; }
    { const char * tb_v1274 = "// Тот, кто её запустил, узнаёт это из .crashed (done == 2). Main и прерывание так не умеют:\n"; *(const char * *)tb_grow(v_lines) = tb_v1274; }
    { const char * tb_v1275 = "// их падение останавливает ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v1275; }
    { const char * tb_v1276 = "TB_API int tb_cell_can_fall(void) { return !tb_in_irq && tb_cur != 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1276; }
    { const char * tb_v1277 = "// кто пишет строку: номер задачи + 1 (прерывание — -1, оно не ждёт)\n"; *(const char * *)tb_grow(v_lines) = tb_v1277; }
