    { const char * tb_v1293 = "        uint64_t *tag = &((uint64_t *)p)[-1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1293; }
    { const char * tb_v1294 = "        tb_cell_refund(*tag, (long long)tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v1294; }
    { const char * tb_v1295 = "        *tag = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1295; }
    { const char * tb_v1296 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1296; }
    { const char * tb_v1297 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1297; }
    { const char * tb_v1298 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1298; }
    { const char * tb_v1299 = "// кусок переходит текущей клетке (взяла из канала)\n"; *(const char * *)tb_grow(v_lines) = tb_v1299; }
    { const char * tb_v1300 = "TB_API void tb_adopt(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1300; }
    { const char * tb_v1301 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v1301; }
    { const char * tb_v1302 = "    if (tb_is_piece(p)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1302; }
    { const char * tb_v1303 = "        uint64_t *tag = &((uint64_t *)p)[-1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1303; }
    { const char * tb_v1304 = "        tb_cell_refund(*tag, (long long)tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v1304; }
    { const char * tb_v1305 = "        uint64_t t = tb_cell_charge(tb_piece((void *)p));\n"; *(const char * *)tb_grow(v_lines) = tb_v1305; }
    { const char * tb_v1306 = "        *tag = t == (uint64_t)-1 ? 0 : t;   // сверх квоты — пусть будет ничьим, клетку не роняем на приёме\n"; *(const char * *)tb_grow(v_lines) = tb_v1306; }
