    { const char * tb_v1368 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1368; }
    { const char * tb_v1369 = "// все прерывания приходят сюда; ответ — кадр, в который вернуться (так переключаются задачи)\n"; *(const char * *)tb_grow(v_lines) = tb_v1369; }
    { const char * tb_v1370 = "__attribute__((used)) static uint64_t *tb_isr(uint64_t *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1370; }
    { const char * tb_v1371 = "    uint64_t v = f[TB_F_VEC];\n"; *(const char * *)tb_grow(v_lines) = tb_v1371; }
    { const char * tb_v1372 = "    if (v < 32) return tb_fault(v, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1372; }
    { const char * tb_v1373 = "    if (v == 48) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1373; }
    { const char * tb_v1374 = "    if (v == 49) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1374; }
    { const char * tb_v1375 = "        // таймер своего ядра процессора (APIC): 1000 раз в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v1375; }
    { const char * tb_v1376 = "        tb_lapic_w(0xB0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1376; }
    { const char * tb_v1377 = "        if (--tb_me()->slice <= 0) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1377; }
