    { const char * tb_v1379 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1379; }
    { const char * tb_v1380 = "    int irq = (int)v - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v1380; }
    { const char * tb_v1381 = "    if (irq == 0) tb_ms++;\n"; *(const char * *)tb_grow(v_lines) = tb_v1381; }
