    { const char * tb_v1388 = "        tb_set_fs(tb_tls_tp(c->run >= 0 ? tb_slots[c->run].tls : c->irq_tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v1388; }
    { const char * tb_v1389 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1389; }
