    { const char * tb_v1393 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v1393; }
    { const char * tb_v1394 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1394; }
    { const char * tb_v1395 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1395; }
