    { const char * tb_v1825 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v1825; }
    { const char * tb_v1826 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1826; }
    { const char * tb_v1827 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1827; }
