    { const char * tb_v2178 = "// Windows: VirtualAlloc тоже даёт нули, и адрес у него всегда кратен 64 КБ — обрезать нечего.\n"; *(const char * *)tb_grow(v_lines) = tb_v2178; }
    { const char * tb_v2179 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v2179; }
    { const char * tb_v2180 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2180; }
    { const char * tb_v2181 = "    char *m = VirtualAlloc(0, (SIZE_T)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2181; }
