    { const char * tb_v2195 = "extern void *mremap(void *old, size_t old_size, size_t new_size, int flags, ...);\n"; *(const char * *)tb_grow(v_lines) = tb_v2195; }
    { const char * tb_v2196 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2196; }
    { const char * tb_v2197 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2197; }
    { const char * tb_v2198 = "    size_t tot = (size_t)size + (size_t)TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v2198; }
    { const char * tb_v2199 = "    char *m = mmap(0, tot, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2199; }
    { const char * tb_v2200 = "    if (m == MAP_FAILED) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2200; }
