    { const char * tb_v2206 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2206; }
    { const char * tb_v2207 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2207; }
    { const char * tb_v2208 = "// страницы по 64 КБ берём у системы пачкой по 4 МБ; пустые страницы возвращаются в запас\n"; *(const char * *)tb_grow(v_lines) = tb_v2208; }
    { const char * tb_v2209 = "TB_API char *tb_gfresh = 0, *tb_gfresh_end = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2209; }
