    { const char * tb_v2211 = "TB_API char *tb_gpage_mem(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2211; }
    { const char * tb_v2212 = "    if (tb_gspare) { void *p = tb_gspare; tb_gspare = *(void **)p; *(void **)p = 0; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2212; }
    { const char * tb_v2213 = "    if (tb_gfresh == tb_gfresh_end) { tb_gfresh = tb_gsys(64 * TB_GPG); tb_gfresh_end = tb_gfresh + 64 * TB_GPG; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2213; }
