    { const char * tb_v2231 = "    return pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2231; }
    { const char * tb_v2232 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2232; }
    { const char * tb_v2233 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v2233; }
    { const char * tb_v2234 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v2234; }
    { const char * tb_v2235 = "TB_INL char *tb_gblock(uintptr_t a, tb_gpage **out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2235; }
    { const char * tb_v2236 = "    if (a < tb_glo || a >= tb_ghi) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2236; }
    { const char * tb_v2237 = "    tb_gpage *pg = tb_gmap_get(a);\n"; *(const char * *)tb_grow(v_lines) = tb_v2237; }
