    { const char * tb_v2661 = "        memset(l->data + old, 0, l->cap / 8 - old);\n"; *(const char * *)tb_grow(v_lines) = tb_v2661; }
    { const char * tb_v2662 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2662; }
    { const char * tb_v2663 = "    long long i = l->len++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2663; }
    { const char * tb_v2664 = "    unsigned long long *w = (unsigned long long *)l->data + (i >> 6), m = 1ULL << (i & 63);\n"; *(const char * *)tb_grow(v_lines) = tb_v2664; }
    { const char * tb_v2665 = "    *w = v ? (*w | m) : (*w & ~m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2665; }
