    { const char * tb_v3291 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v3291; }
    { const char * tb_v3292 = "    unsigned long long span = (unsigned long long)(b - a) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3292; }
