    { const char * tb_v3567 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
