    { const char * tb_v3591 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3591; }
    { const char * tb_v3592 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3592; }
    { const char * tb_v3593 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3593; }
    { const char * tb_v3594 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3594; }
    { const char * tb_v3595 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3595; }
    { const char * tb_v3596 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3596; }
    { const char * tb_v3597 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3597; }
    { const char * tb_v3598 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3598; }
