    { const char * tb_v3746 = "TB_API void tb_mem_report(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v3746; }
    { const char * tb_v3747 = "TB_INL int tb_memchk(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3747; }
    { const char * tb_v3748 = "    if (TB_RARE(tb_mem_check < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3748; }
    { const char * tb_v3749 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3749; }
    { const char * tb_v3750 = "        tb_mem_check = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3750; }
    { const char * tb_v3751 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3751; }
    { const char * tb_v3752 = "        const char *e = getenv(\"TB_MEM_CHECK\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3752; }
    { const char * tb_v3753 = "        tb_mem_check = e && e[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v3753; }
    { const char * tb_v3754 = "        if (tb_mem_check) atexit(tb_mem_report);\n"; *(const char * *)tb_grow(v_lines) = tb_v3754; }
    { const char * tb_v3755 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3755; }
    { const char * tb_v3756 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3756; }
    { const char * tb_v3757 = "    return tb_mem_check;\n"; *(const char * *)tb_grow(v_lines) = tb_v3757; }
    { const char * tb_v3758 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3758; }
    { const char * tb_v3759 = "static void tb_mem_lock(void) { while (__sync_lock_test_and_set(&tb_mem_spin, 1)) { } }\n"; *(const char * *)tb_grow(v_lines) = tb_v3759; }
    { const char * tb_v3760 = "static void tb_mem_unlock(void) { __sync_lock_release(&tb_mem_spin); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3760; }
    { const char * tb_v3761 = "TB_COLD static void tb_mem_die(int line, const char *what, int at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3761; }
    { const char * tb_v3762 = "    char buf[200];\n"; *(const char * *)tb_grow(v_lines) = tb_v3762; }
    { const char * tb_v3763 = "    if (at > 0) snprintf(buf, sizeof buf, \"%s (блок из new_mem в строке %d)\", what, at);\n"; *(const char * *)tb_grow(v_lines) = tb_v3763; }
    { const char * tb_v3764 = "    else snprintf(buf, sizeof buf, \"%s\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v3764; }
    { const char * tb_v3765 = "    tb_mem_check = 0;   // программа падает: отчёт о неосвобождённом не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v3765; }
    { const char * tb_v3766 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3766; }
    { const char * tb_v3767 = "    tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v3767; }
    { const char * tb_v3768 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3768; }
    { const char * tb_v3769 = "TB_API void tb_mem_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3769; }
    { const char * tb_v3770 = "    long long n = 0, bytes = 0; int first = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3770; }
    { const char * tb_v3771 = "    for (long long i = 0; i < tb_mem_n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3771; }
    { const char * tb_v3772 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3772; }
    { const char * tb_v3773 = "    if (n && tb_mem_check) fprintf(stderr, \"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\", n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v3773; }
    { const char * tb_v3774 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3774; }
    { const char * tb_v3775 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v3775; }
    { const char * tb_v3776 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3776; }
    { const char * tb_v3777 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3777; }
    { const char * tb_v3778 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3778; }
    { const char * tb_v3779 = "    for (long long i = 0; i < tb_mem_n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3779; }
    { const char * tb_v3780 = "        tb_memb *b = &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3780; }
    { const char * tb_v3781 = "        uintptr_t lo = b->a - sizeof(tb_memh), hi = b->a + b->n + TB_MEM_GUARD;\n"; *(const char * *)tb_grow(v_lines) = tb_v3781; }
    { const char * tb_v3782 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3782; }
    { const char * tb_v3783 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3783; }
    { const char * tb_v3784 = "            char buf[160];\n"; *(const char * *)tb_grow(v_lines) = tb_v3784; }
    { const char * tb_v3785 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v3785; }
    { const char * tb_v3786 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3786; }
    { const char * tb_v3787 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3787; }
    { const char * tb_v3788 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3788; }
    { const char * tb_v3789 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3789; }
    { const char * tb_v3790 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3790; }
    { const char * tb_v3791 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3791; }
    { const char * tb_v3792 = "static tb_memb *tb_mem_find(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3792; }
    { const char * tb_v3793 = "    for (long long i = tb_mem_n - 1; i >= 0; i--) if (tb_mem_all[i].a == a) return &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3793; }
    { const char * tb_v3794 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3794; }
    { const char * tb_v3795 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3795; }
    { const char * tb_v3796 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v3796; }
    { const char * tb_v3797 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v3797; }
    { const char * tb_v3798 = "TB_INL long long tb_rd8(long long a, int line) { TB_TOUCH(a, 1); return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3798; }
    { const char * tb_v3799 = "TB_INL long long tb_rd16(long long a, int line) { TB_TOUCH(a, 2); return *(volatile uint16_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3799; }
    { const char * tb_v3800 = "TB_INL long long tb_rd32(long long a, int line) { TB_TOUCH(a, 4); return *(volatile uint32_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3800; }
    { const char * tb_v3801 = "TB_INL long long tb_rd64(long long a, int line) { TB_TOUCH(a, 8); return (long long)*(volatile uint64_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3801; }
    { const char * tb_v3802 = "TB_INL void tb_wr8(long long a, long long v, int line) { TB_TOUCH(a, 1); *(volatile uint8_t *)(uintptr_t)a = (uint8_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3802; }
    { const char * tb_v3803 = "TB_INL void tb_wr16(long long a, long long v, int line) { TB_TOUCH(a, 2); *(volatile uint16_t *)(uintptr_t)a = (uint16_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3803; }
    { const char * tb_v3804 = "TB_INL void tb_wr32(long long a, long long v, int line) { TB_TOUCH(a, 4); *(volatile uint32_t *)(uintptr_t)a = (uint32_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3804; }
    { const char * tb_v3805 = "TB_INL void tb_wr64(long long a, long long v, int line) { TB_TOUCH(a, 8); *(volatile uint64_t *)(uintptr_t)a = (uint64_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3805; }
    { const char * tb_v3806 = "TB_INL long long tb_addr_of(tb_list *l) { return (long long)(uintptr_t)l->data; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3806; }
    { const char * tb_v3807 = "// new_mem(байт): новый блок, заполнен нулями; адрес — число. Может не получиться (нет памяти)\n"; *(const char * *)tb_grow(v_lines) = tb_v3807; }
    { const char * tb_v3808 = "TB_API long long tb_new_mem(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3808; }
    { const char * tb_v3809 = "    if (n <= 0) { tb_err = \"new_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3809; }
    { const char * tb_v3810 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"new_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3810; }
    { const char * tb_v3811 = "    int chk = tb_memchk();\n"; *(const char * *)tb_grow(v_lines) = tb_v3811; }
    { const char * tb_v3812 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3812; }
    { const char * tb_v3813 = "    tb_mem_soft(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3813; }
    { const char * tb_v3814 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3814; }
    { const char * tb_v3815 = "    tb_memh *h = malloc(sizeof(tb_memh) + (size_t)n + (chk ? TB_MEM_GUARD : 0));\n"; *(const char * *)tb_grow(v_lines) = tb_v3815; }
    { const char * tb_v3816 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3816; }
    { const char * tb_v3817 = "    tb_mem_soft(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3817; }
    { const char * tb_v3818 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3818; }
    { const char * tb_v3819 = "    if (!h) { tb_err = \"new_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3819; }
    { const char * tb_v3820 = "    h->size = (uint64_t)n; h->magic = TB_MEM_LIVE;\n"; *(const char * *)tb_grow(v_lines) = tb_v3820; }
    { const char * tb_v3821 = "    unsigned char *p = (unsigned char *)(h + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3821; }
    { const char * tb_v3822 = "    memset(p, 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3822; }
    { const char * tb_v3823 = "    if (chk) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3823; }
    { const char * tb_v3824 = "        memset(p + n, 0xFB, TB_MEM_GUARD);\n"; *(const char * *)tb_grow(v_lines) = tb_v3824; }
    { const char * tb_v3825 = "        tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3825; }
    { const char * tb_v3826 = "        if (tb_mem_n == tb_mem_cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3826; }
    { const char * tb_v3827 = "            long long nc = tb_mem_cap ? tb_mem_cap * 2 : 256;\n"; *(const char * *)tb_grow(v_lines) = tb_v3827; }
    { const char * tb_v3828 = "            tb_memb *all = realloc(tb_mem_all, (size_t)nc * sizeof(tb_memb));\n"; *(const char * *)tb_grow(v_lines) = tb_v3828; }
    { const char * tb_v3829 = "            if (!all) tb_mem_die(line, \"не хватило памяти\", 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3829; }
    { const char * tb_v3830 = "            tb_mem_all = all; tb_mem_cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v3830; }
    { const char * tb_v3831 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3831; }
    { const char * tb_v3832 = "        tb_memb b = { (uintptr_t)p, (uint64_t)n, 1, line, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v3832; }
    { const char * tb_v3833 = "        tb_mem_all[tb_mem_n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3833; }
    { const char * tb_v3834 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3834; }
    { const char * tb_v3835 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3835; }
    { const char * tb_v3836 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3836; }
    { const char * tb_v3837 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3837; }
    { const char * tb_v3838 = "// проверить адрес для free_mem / grow_mem; вернуть заголовок блока\n"; *(const char * *)tb_grow(v_lines) = tb_v3838; }
    { const char * tb_v3839 = "static tb_memh *tb_mem_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3839; }
    { const char * tb_v3840 = "    char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3840; }
    { const char * tb_v3841 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3841; }
    { const char * tb_v3842 = "        tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3842; }
    { const char * tb_v3843 = "        tb_memb *b = tb_mem_find((uintptr_t)a);\n"; *(const char * *)tb_grow(v_lines) = tb_v3843; }
    { const char * tb_v3844 = "        if (!b) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem\", who); tb_mem_die(line, buf, 0); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3844; }
    { const char * tb_v3845 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3845; }
    { const char * tb_v3846 = "            snprintf(buf, sizeof buf, \"%s: блок уже освобождён в строке %d\", who, b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v3846; }
    { const char * tb_v3847 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3847; }
    { const char * tb_v3848 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3848; }
    { const char * tb_v3849 = "        const unsigned char *g = (const unsigned char *)(uintptr_t)a + b->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3849; }
    { const char * tb_v3850 = "        for (int i = 0; i < TB_MEM_GUARD; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3850; }
    { const char * tb_v3851 = "            if (g[i] != 0xFB) tb_mem_die(line, \"кто-то писал за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3851; }
    { const char * tb_v3852 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3852; }
    { const char * tb_v3853 = "        return (tb_memh *)(uintptr_t)a - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3853; }
    { const char * tb_v3854 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3854; }
    { const char * tb_v3855 = "    tb_memh *h = (tb_memh *)(uintptr_t)a - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3855; }
    { const char * tb_v3856 = "    if (h->magic == TB_MEM_DEAD) { snprintf(buf, sizeof buf, \"%s: блок уже освобождён\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3856; }
    { const char * tb_v3857 = "    if (h->magic != TB_MEM_LIVE) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem или блок уже освобождён (точнее покажет TB_MEM_CHECK=1)\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3857; }
    { const char * tb_v3858 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3858; }
    { const char * tb_v3859 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3859; }
    { const char * tb_v3860 = "// TB_MEM_CHECK: блок не отдаётся обратно, а помечается — чтобы поймать чтение после free_mem\n"; *(const char * *)tb_grow(v_lines) = tb_v3860; }
    { const char * tb_v3861 = "static void tb_mem_bury(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3861; }
    { const char * tb_v3862 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v3862; }
