    { const char * tb_v4083 = "    TB_TOUCH(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4083; }
    { const char * tb_v4084 = "    if (bn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4084; }
    { const char * tb_v4085 = "        if (x < 0 || (bn < 63 && (x >> bn))) tb_crash(line, \"число не влезает в поле bits: от 0 до 2 в степени N без единицы\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4085; }
    { const char * tb_v4086 = "        uint64_t m = bn < 64 ? (((uint64_t)1 << bn) - 1) << bo : ~(uint64_t)0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4086; }
    { const char * tb_v4087 = "        uint64_t v = tb_shape_raw(p, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4087; }
    { const char * tb_v4088 = "        if (k & 32) v = tb_shape_swap(v, nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v4088; }
    { const char * tb_v4089 = "        v = (v & ~m) | (((uint64_t)x << bo) & m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4089; }
