    { const char * tb_v4126 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v4126; }
    { const char * tb_v4127 = "    if (!tb_in_irq)\n"; *(const char * *)tb_grow(v_lines) = tb_v4127; }
