    { const char * tb_v5043 = "    if (w <= 0 || h <= 0 || (long long)w * h > (1ll << 26)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5043; }
    { const char * tb_v5044 = "    while (at < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5044; }
    { const char * tb_v5045 = "        int b = d[at++];\n"; *(const char * *)tb_grow(v_lines) = tb_v5045; }
