    { const char * tb_v5052 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5052; }
    { const char * tb_v5053 = "        if (b != 0x2C || at + 9 > n) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v5053; }
    { const char * tb_v5054 = "        int fx = d[at] | d[at + 1] << 8, fy = d[at + 2] | d[at + 3] << 8, fw = d[at + 4] | d[at + 5] << 8, fh = d[at + 6] | d[at + 7] << 8, ff = d[at + 8];\n"; *(const char * *)tb_grow(v_lines) = tb_v5054; }
