    { const char * tb_v5192 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5192; }
    { const char * tb_v5193 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5193; }
    { const char * tb_v5194 = "// снимок кадра (что нарисовано сейчас) — новая картинка; потом draw_image рисует её за один раз\n"; *(const char * *)tb_grow(v_lines) = tb_v5194; }
    { const char * tb_v5195 = "TB_API long long tb_screen_image(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5195; }
    { const char * tb_v5196 = "    if (!tb_px) { tb_err = \"окно ещё не открыто\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5196; }
    { const char * tb_v5197 = "    size_t n = (size_t)tb_gw * tb_gh, need = tb_imgpx_n + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5197; }
