    { const char * tb_v5203 = "    for (size_t i = 0; i < n; i++) tb_imgpx[tb_imgpx_n + i] = tb_px[i] | 0xFF000000u;\n"; *(const char * *)tb_grow(v_lines) = tb_v5203; }
    { const char * tb_v5204 = "    tb_imgs[tb_nimg].w = tb_gw; tb_imgs[tb_nimg].h = tb_gh; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5204; }
    { const char * tb_v5205 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5205; }
    { const char * tb_v5206 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5206; }
    { const char * tb_v5207 = "    return tb_nimg++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5207; }
    { const char * tb_v5208 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5208; }
    { const char * tb_v5209 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5209; }
    { const char * tb_v5210 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5210; }
    { const char * tb_v5211 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5211; }
    { const char * tb_v5212 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v5212; }
    { const char * tb_v5213 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v5213; }
    { const char * tb_v5214 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5214; }
    { const char * tb_v5215 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5215; }
    { const char * tb_v5216 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5216; }
    { const char * tb_v5217 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5217; }
    { const char * tb_v5218 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5218; }
    { const char * tb_v5219 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5219; }
    { const char * tb_v5220 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5220; }
    { const char * tb_v5221 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5221; }
    { const char * tb_v5222 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5222; }
    { const char * tb_v5223 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5223; }
    { const char * tb_v5224 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v5224; }
    { const char * tb_v5225 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5225; }
    { const char * tb_v5226 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5226; }
    { const char * tb_v5227 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5227; }
    { const char * tb_v5228 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v5228; }
    { const char * tb_v5229 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5229; }
    { const char * tb_v5230 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5230; }
    { const char * tb_v5231 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5231; }
    { const char * tb_v5232 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v5232; }
    { const char * tb_v5233 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5233; }
    { const char * tb_v5234 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5234; }
    { const char * tb_v5235 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v5235; }
    { const char * tb_v5236 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v5236; }
    { const char * tb_v5237 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5237; }
    { const char * tb_v5238 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v5238; }
    { const char * tb_v5239 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5239; }
    { const char * tb_v5240 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5240; }
    { const char * tb_v5241 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5241; }
    { const char * tb_v5242 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5242; }
    { const char * tb_v5243 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5243; }
    { const char * tb_v5244 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5244; }
    { const char * tb_v5245 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v5245; }
    { const char * tb_v5246 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5246; }
    { const char * tb_v5247 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v5247; }
    { const char * tb_v5248 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5248; }
    { const char * tb_v5249 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v5249; }
    { const char * tb_v5250 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5250; }
    { const char * tb_v5251 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5251; }
    { const char * tb_v5252 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5252; }
    { const char * tb_v5253 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5253; }
    { const char * tb_v5254 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5254; }
    { const char * tb_v5255 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5255; }
    { const char * tb_v5256 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v5256; }
    { const char * tb_v5257 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5257; }
    { const char * tb_v5258 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v5258; }
    { const char * tb_v5259 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5259; }
    { const char * tb_v5260 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5260; }
    { const char * tb_v5261 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5261; }
    { const char * tb_v5262 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5262; }
    { const char * tb_v5263 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v5263; }
    { const char * tb_v5264 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5264; }
    { const char * tb_v5265 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5265; }
    { const char * tb_v5266 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v5266; }
    { const char * tb_v5267 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v5267; }
    { const char * tb_v5268 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5268; }
    { const char * tb_v5269 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5269; }
    { const char * tb_v5270 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5270; }
    { const char * tb_v5271 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5271; }
    { const char * tb_v5272 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5272; }
    { const char * tb_v5273 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v5273; }
    { const char * tb_v5274 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5274; }
    { const char * tb_v5275 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v5275; }
    { const char * tb_v5276 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5276; }
    { const char * tb_v5277 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v5277; }
    { const char * tb_v5278 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5278; }
    { const char * tb_v5279 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5279; }
    { const char * tb_v5280 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5280; }
    { const char * tb_v5281 = "    if (u > 0xFFFF) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5281; }
    { const char * tb_v5282 = "    unsigned segs = tb_u16(f, c + 6) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5282; }
    { const char * tb_v5283 = "    size_t ends = c + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, ranges = deltas + 2 * segs;\n"; *(const char * *)tb_grow(v_lines) = tb_v5283; }
    { const char * tb_v5284 = "    for (unsigned i = 0; i < segs; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5284; }
