    { const char * tb_v5568 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v5568; }
    { const char * tb_v5569 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v5569; }
    { const char * tb_v5570 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v5570; }
    { const char * tb_v5571 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v5571; }
    { const char * tb_v5572 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5572; }
    { const char * tb_v5573 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v5573; }
    { const char * tb_v5574 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5574; }
    { const char * tb_v5575 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5575; }
    { const char * tb_v5576 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5576; }
    { const char * tb_v5577 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5577; }
    { const char * tb_v5578 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5578; }
    { const char * tb_v5579 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v5579; }
    { const char * tb_v5580 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5580; }
    { const char * tb_v5581 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5581; }
    { const char * tb_v5582 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5582; }
    { const char * tb_v5583 = "// 3D с картинкой (mesh_image): у треугольника ещё запись текстуры — плоскости u·W и v·W (по 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v5583; }
    { const char * tb_v5584 = "// и сама картинка; номер записи — в pad его плоскости глубины, а в m ещё бит 29\n"; *(const char * *)tb_grow(v_lines) = tb_v5584; }
    { const char * tb_v5585 = "typedef struct { int64_t au, bu, cu, av, bv, cv; uint32_t off, w, h, pad; } tb_gtex_t;   // 64 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5585; }
    { const char * tb_v5586 = "enum { TB_GT_CAP = 16384 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5586; }
    { const char * tb_v5587 = "TB_API tb_gtex_t *tb_gtex = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5587; }
    { const char * tb_v5588 = "TB_API int tb_gtn = 0, tb_gpu_tex = 0;   // записей в текущем наборе; видеокарта умеет картинки на сетках\n"; *(const char * *)tb_grow(v_lines) = tb_v5588; }
    { const char * tb_v5589 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v5589; }
    { const char * tb_v5590 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v5590; }
    { const char * tb_v5591 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v5591; }
    { const char * tb_v5592 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5592; }
    { const char * tb_v5593 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v5593; }
    { const char * tb_v5594 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v5594; }
    { const char * tb_v5595 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v5595; }
    { const char * tb_v5596 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v5596; }
    { const char * tb_v5597 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5597; }
    { const char * tb_v5598 = "typedef struct { int32_t r[16]; } tb_grec;   // 4 строки: поворот × 2^30 и сдвиг × 4096 (3), свет в сетке (x, y, z × 2^14, фон × 256; фон -1 — без света)\n"; *(const char * *)tb_grow(v_lines) = tb_v5598; }
    { const char * tb_v5599 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5599; }
    { const char * tb_v5600 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5600; }
    { const char * tb_v5601 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v5601; }
    { const char * tb_v5602 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v5602; }
    { const char * tb_v5603 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v5603; }
    { const char * tb_v5604 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5604; }
    { const char * tb_v5605 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v5605; }
    { const char * tb_v5606 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v5606; }
    { const char * tb_v5607 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v5607; }
    { const char * tb_v5608 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v5608; }
    { const char * tb_v5609 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5609; }
    { const char * tb_v5610 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5610; }
    { const char * tb_v5611 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v5611; }
    { const char * tb_v5612 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5612; }
    { const char * tb_v5613 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v5613; }
    { const char * tb_v5614 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v5614; }
    { const char * tb_v5615 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5615; }
    { const char * tb_v5616 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v5616; }
    { const char * tb_v5617 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v5617; }
    { const char * tb_v5618 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5618; }
    { const char * tb_v5619 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v5619; }
    { const char * tb_v5620 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5620; }
    { const char * tb_v5621 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v5621; }
    { const char * tb_v5622 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5622; }
    { const char * tb_v5623 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5623; }
    { const char * tb_v5624 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5624; }
    { const char * tb_v5625 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v5625; }
    { const char * tb_v5626 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5626; }
    { const char * tb_v5627 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v5627; }
    { const char * tb_v5628 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5628; }
    { const char * tb_v5629 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5629; }
    { const char * tb_v5630 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5630; }
    { const char * tb_v5631 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v5631; }
    { const char * tb_v5632 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5632; }
    { const char * tb_v5633 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5633; }
    { const char * tb_v5634 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v5634; }
    { const char * tb_v5635 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5635; }
    { const char * tb_v5636 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v5636; }
    { const char * tb_v5637 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v5637; }
    { const char * tb_v5638 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5638; }
    { const char * tb_v5639 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5639; }
    { const char * tb_v5640 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v5640; }
    { const char * tb_v5641 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5641; }
    { const char * tb_v5642 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5642; }
    { const char * tb_v5643 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5643; }
    { const char * tb_v5644 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5644; }
    { const char * tb_v5645 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5645; }
    { const char * tb_v5646 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5646; }
    { const char * tb_v5647 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5647; }
    { const char * tb_v5648 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5648; }
    { const char * tb_v5649 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v5649; }
    { const char * tb_v5650 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v5650; }
    { const char * tb_v5651 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5651; }
    { const char * tb_v5652 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5652; }
    { const char * tb_v5653 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5653; }
    { const char * tb_v5654 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5654; }
    { const char * tb_v5655 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5655; }
    { const char * tb_v5656 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v5656; }
    { const char * tb_v5657 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5657; }
    { const char * tb_v5658 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v5658; }
    { const char * tb_v5659 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5659; }
    { const char * tb_v5660 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v5660; }
    { const char * tb_v5661 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5661; }
    { const char * tb_v5662 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5662; }
    { const char * tb_v5663 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5663; }
    { const char * tb_v5664 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v5664; }
    { const char * tb_v5665 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5665; }
    { const char * tb_v5666 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v5666; }
    { const char * tb_v5667 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5667; }
    { const char * tb_v5668 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5668; }
    { const char * tb_v5669 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5669; }
    { const char * tb_v5670 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5670; }
    { const char * tb_v5671 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5671; }
    { const char * tb_v5672 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5672; }
    { const char * tb_v5673 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5673; }
    { const char * tb_v5674 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5674; }
    { const char * tb_v5675 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v5675; }
    { const char * tb_v5676 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5676; }
    { const char * tb_v5677 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5677; }
    { const char * tb_v5678 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5678; }
    { const char * tb_v5679 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5679; }
    { const char * tb_v5680 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5680; }
    { const char * tb_v5681 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5681; }
    { const char * tb_v5682 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5682; }
    { const char * tb_v5683 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v5683; }
    { const char * tb_v5684 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5684; }
    { const char * tb_v5685 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v5685; }
    { const char * tb_v5686 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5686; }
    { const char * tb_v5687 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5687; }
    { const char * tb_v5688 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v5688; }
    { const char * tb_v5689 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5689; }
    { const char * tb_v5690 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5690; }
    { const char * tb_v5691 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v5691; }
    { const char * tb_v5692 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5692; }
    { const char * tb_v5693 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5693; }
    { const char * tb_v5694 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5694; }
    { const char * tb_v5695 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5695; }
    { const char * tb_v5696 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5696; }
    { const char * tb_v5697 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5697; }
    { const char * tb_v5698 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v5698; }
    { const char * tb_v5699 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5699; }
    { const char * tb_v5700 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v5700; }
    { const char * tb_v5701 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5701; }
    { const char * tb_v5702 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5702; }
    { const char * tb_v5703 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5703; }
    { const char * tb_v5704 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v5704; }
    { const char * tb_v5705 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5705; }
    { const char * tb_v5706 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v5706; }
    { const char * tb_v5707 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5707; }
    { const char * tb_v5708 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v5708; }
    { const char * tb_v5709 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5709; }
    { const char * tb_v5710 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (1u << 29) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5710; }
    { const char * tb_v5711 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5711; }
    { const char * tb_v5712 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v5712; }
    { const char * tb_v5713 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v5713; }
    { const char * tb_v5714 = "TB_API void tb_gpu_triangle(const long long *t, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5714; }
    { const char * tb_v5715 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 1u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5715; }
    { const char * tb_v5716 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5716; }
    { const char * tb_v5717 = "// треугольник сетки (3D): как треугольник, плюс плоскость глубины в tb_gplane\n"; *(const char * *)tb_grow(v_lines) = tb_v5717; }
    { const char * tb_v5718 = "TB_API void tb_gpu_tri3(const long long *t, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5718; }
    { const char * tb_v5719 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5719; }
    { const char * tb_v5720 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin);\n"; *(const char * *)tb_grow(v_lines) = tb_v5720; }
    { const char * tb_v5721 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v5721; }
    { const char * tb_v5722 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5722; }
    { const char * tb_v5723 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v5723; }
    { const char * tb_v5724 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5724; }
    { const char * tb_v5725 = "// треугольник сетки с картинкой: плоскость глубины и запись текстуры; m = 2 | бит 29 | (место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5725; }
    { const char * tb_v5726 = "// какой конвейер у фигуры: 0 — 2D, 1 — 3D (глубина), 2 — 3D с картинкой\n"; *(const char * *)tb_grow(v_lines) = tb_v5726; }
    { const char * tb_v5727 = "TB_INL int tb_gkind(uint32_t m) { return (m & 0xC0000003u) != 2u ? 0 : (m >> 29) & 1u ? 2 : 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5727; }
    { const char * tb_v5728 = "TB_API void tb_gpu_tri3t(const long long *t, long long c, const uint32_t *pl, const tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5728; }
    { const char * tb_v5729 = "    if (tb_gin == TB_GI_CAP || tb_gtn == TB_GT_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v5729; }
    { const char * tb_v5730 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin), gt = (uint32_t)(tb_gslot * TB_GT_CAP + tb_gtn++);\n"; *(const char * *)tb_grow(v_lines) = tb_v5730; }
    { const char * tb_v5731 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v5731; }
    { const char * tb_v5732 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = gt;\n"; *(const char * *)tb_grow(v_lines) = tb_v5732; }
    { const char * tb_v5733 = "    tb_gtex[gt] = *tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v5733; }
    { const char * tb_v5734 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (1u << 29) | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v5734; }
    { const char * tb_v5735 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5735; }
    { const char * tb_v5736 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5736; }
    { const char * tb_v5737 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5737; }
    { const char * tb_v5738 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5738; }
    { const char * tb_v5739 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5739; }
    { const char * tb_v5740 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v5740; }
    { const char * tb_v5741 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5741; }
    { const char * tb_v5742 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5742; }
    { const char * tb_v5743 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v5743; }
    { const char * tb_v5744 = "    long long x1 = x + 8 * size > tb_gw ? tb_gw : x + 8 * size, y1 = y + 16 * size > tb_gh ? tb_gh : y + 16 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v5744; }
    { const char * tb_v5745 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v5745; }
