    { const char * tb_v9011 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v9011; }
    { const char * tb_v9012 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v9012; }
