    { const char * tb_v9067 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v9067; }
    { const char * tb_v9068 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9068; }
    { const char * tb_v9069 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9069; }
