    { const char * tb_v9086 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v9086; }
    { const char * tb_v9087 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9087; }
    { const char * tb_v9088 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9088; }
    { const char * tb_v9089 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9089; }
    { const char * tb_v9090 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9090; }
    { const char * tb_v9091 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9091; }
    { const char * tb_v9092 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9092; }
