    { const char * tb_v9103 = "            tb_cover(i, j, (uint32_t)c, f * f);\n"; *(const char * *)tb_grow(v_lines) = tb_v9103; }
    { const char * tb_v9104 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9104; }
