    { const char * tb_v9106 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9106; }
    { const char * tb_v9107 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v9107; }
    { const char * tb_v9108 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9108; }
    { const char * tb_v9109 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v9109; }
    { const char * tb_v9110 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9110; }
    { const char * tb_v9111 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v9111; }
    { const char * tb_v9112 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9112; }
    { const char * tb_v9113 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9113; }
    { const char * tb_v9114 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9114; }
    { const char * tb_v9115 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9115; }
