    { const char * tb_v9118 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9118; }
    { const char * tb_v9119 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v9119; }
    { const char * tb_v9120 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9120; }
    { const char * tb_v9121 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9121; }
    { const char * tb_v9122 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9122; }
    { const char * tb_v9123 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v9123; }
    { const char * tb_v9124 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9124; }
    { const char * tb_v9125 = "    if (!tb_px || w <= 0 || h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9125; }
    { const char * tb_v9126 = "    int m = tb_corners(corners);\n"; *(const char * *)tb_grow(v_lines) = tb_v9126; }
    { const char * tb_v9127 = "    if (r < 0) r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9127; }
    { const char * tb_v9128 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9128; }
    { const char * tb_v9129 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9129; }
    { const char * tb_v9130 = "    if (tb_gpu_on) {   // видеокарта: пока без сглаживания\n"; *(const char * *)tb_grow(v_lines) = tb_v9130; }
    { const char * tb_v9131 = "        tb_gpu_rect(x + r, y, w - 2 * r, h, c); tb_gpu_rect(x, y + r, r, h - 2 * r, c); tb_gpu_rect(x + w - r, y + r, r, h - 2 * r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9131; }
    { const char * tb_v9132 = "        tb_gpu_circle(x + r, y + r, r, c); tb_gpu_circle(x + w - 1 - r, y + r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9132; }
    { const char * tb_v9133 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9133; }
    { const char * tb_v9134 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9134; }
    { const char * tb_v9135 = "    if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9135; }
    { const char * tb_v9136 = "    uint32_t cc = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9136; }
    { const char * tb_v9137 = "    long long y0 = y < 0 ? 0 : y, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9137; }
    { const char * tb_v9138 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9138; }
    { const char * tb_v9139 = "        long long row = j - y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9139; }
    { const char * tb_v9140 = "        int top = row < r, bot = row >= h - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9140; }
    { const char * tb_v9141 = "        int lc = (top && (m & 1)) || (bot && (m & 4)), rc = (top && (m & 2)) || (bot && (m & 8));\n"; *(const char * *)tb_grow(v_lines) = tb_v9141; }
    { const char * tb_v9142 = "        double cy = top ? y + r - 0.5 : y + h - r - 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9142; }
    { const char * tb_v9143 = "        // середина строки — сплошняком\n"; *(const char * *)tb_grow(v_lines) = tb_v9143; }
    { const char * tb_v9144 = "        long long a = x + (lc ? r : 0), b = x + w - (rc ? r : 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9144; }
    { const char * tb_v9145 = "        if (a < 0) a = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9145; }
    { const char * tb_v9146 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v9146; }
    { const char * tb_v9147 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9147; }
    { const char * tb_v9148 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v9148; }
    { const char * tb_v9149 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v9149; }
    { const char * tb_v9150 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9150; }
    { const char * tb_v9151 = "            if (!(side ? rc : lc)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9151; }
