    { const char * tb_v9153 = "            long long i0 = side ? x + w - r : x, i1 = side ? x + w : x + r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9153; }
    { const char * tb_v9154 = "            for (long long i = i0; i < i1; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9154; }
    { const char * tb_v9155 = "                double dx = i + 0.5 - (cx + 0.5), dy = j + 0.5 - (cy + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9155; }
    { const char * tb_v9156 = "                double d = sqrt(dx * dx + dy * dy);\n"; *(const char * *)tb_grow(v_lines) = tb_v9156; }
    { const char * tb_v9157 = "                tb_cover(i, j, cc, r - d + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v9157; }
    { const char * tb_v9158 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9158; }
    { const char * tb_v9159 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9159; }
    { const char * tb_v9160 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9160; }
    { const char * tb_v9161 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9161; }
    { const char * tb_v9162 = "// размыть то, что уже нарисовано в прямоугольнике (матовое стекло, мягкий фон): три прохода «ящиком»\n"; *(const char * *)tb_grow(v_lines) = tb_v9162; }
    { const char * tb_v9163 = "// размытие одного ряда (n точек с шагом step в буфере b) скользящей суммой окна 2r+1; tmp — n точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9163; }
    { const char * tb_v9164 = "TB_INL void tb_blur_run(uint32_t *b, long long n, long long step, long long r, uint32_t *tmp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9164; }
    { const char * tb_v9165 = "    for (long long k = 0; k < n; k++) tmp[k] = b[k * step];\n"; *(const char * *)tb_grow(v_lines) = tb_v9165; }
    { const char * tb_v9166 = "    long long win = 2 * r + 1, sr = 0, sg = 0, sb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9166; }
    { const char * tb_v9167 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v9167; }
    { const char * tb_v9168 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9168; }
    { const char * tb_v9169 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9169; }
    { const char * tb_v9170 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v9170; }
    { const char * tb_v9171 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9171; }
    { const char * tb_v9172 = "    for (long long k = 0; k < n; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9172; }
    { const char * tb_v9173 = "        uint64_t vr = ((uint64_t)sr * mul + (1u << 23)) >> 24, vg = ((uint64_t)sg * mul + (1u << 23)) >> 24, vb = ((uint64_t)sb * mul + (1u << 23)) >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v9173; }
    { const char * tb_v9174 = "        b[k * step] = (uint32_t)((vr > 255 ? 255 : vr) << 16 | (vg > 255 ? 255 : vg) << 8 | (vb > 255 ? 255 : vb));\n"; *(const char * *)tb_grow(v_lines) = tb_v9174; }
    { const char * tb_v9175 = "        uint32_t out = tmp[k - r < 0 ? 0 : k - r], in = tmp[k + r + 1 >= n ? n - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9175; }
