    { const char * tb_v9196 = "                long long sx = x0 + xx * 2, sy = y0 + yy * 2, sx2 = sx + 1 < x1 ? sx + 1 : sx, sy2 = sy + 1 < y1 ? sy + 1 : sy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9196; }
    { const char * tb_v9197 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9197; }
    { const char * tb_v9198 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v9198; }
    { const char * tb_v9199 = "                    | (((p >> 8 & 255) + (q >> 8 & 255) + (u >> 8 & 255) + (v >> 8 & 255) + 2) / 4) << 8\n"; *(const char * *)tb_grow(v_lines) = tb_v9199; }
    { const char * tb_v9200 = "                    | (((p & 255) + (q & 255) + (u & 255) + (v & 255) + 2) / 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9200; }
    { const char * tb_v9201 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9201; }
    { const char * tb_v9202 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9202; }
    { const char * tb_v9203 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9203; }
