    { const char * tb_v9205 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9205; }
    { const char * tb_v9206 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v9206; }
    { const char * tb_v9207 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9207; }
    { const char * tb_v9208 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v9208; }
    { const char * tb_v9209 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v9209; }
    { const char * tb_v9210 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9210; }
