    { const char * tb_v9215 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v9215; }
    { const char * tb_v9216 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9216; }
    { const char * tb_v9217 = "                for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9217; }
    { const char * tb_v9218 = "                    long long a = (p >> sh & 255) * (256 - tx) + (q >> sh & 255) * tx, c = (u >> sh & 255) * (256 - tx) + (v >> sh & 255) * tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9218; }
    { const char * tb_v9219 = "                    o |= (uint32_t)(((a * (256 - ty) + c * ty + 32768) >> 16) & 255) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9219; }
    { const char * tb_v9220 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v9220; }
    { const char * tb_v9221 = "                tb_px[(y0 + yy) * tb_gw + x0 + xx] = o;\n"; *(const char * *)tb_grow(v_lines) = tb_v9221; }
    { const char * tb_v9222 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9222; }
    { const char * tb_v9223 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9223; }
    { const char * tb_v9224 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v9224; }
    { const char * tb_v9225 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v9225; }
    { const char * tb_v9226 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9226; }
    { const char * tb_v9227 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9227; }
    { const char * tb_v9228 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9228; }
    { const char * tb_v9229 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9229; }
    { const char * tb_v9230 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9230; }
    { const char * tb_v9231 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v9231; }
    { const char * tb_v9232 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9232; }
    { const char * tb_v9233 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v9233; }
    { const char * tb_v9234 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9234; }
