    { const char * tb_v9241 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9241; }
    { const char * tb_v9242 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9242; }
    { const char * tb_v9243 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9243; }
    { const char * tb_v9244 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9244; }
