    { const char * tb_v9254 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9254; }
    { const char * tb_v9255 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v9255; }
    { const char * tb_v9256 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9256; }
    { const char * tb_v9257 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9257; }
    { const char * tb_v9258 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v9258; }
    { const char * tb_v9259 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v9259; }
    { const char * tb_v9260 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v9260; }
    { const char * tb_v9261 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v9261; }
    { const char * tb_v9262 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9262; }
    { const char * tb_v9263 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v9263; }
    { const char * tb_v9264 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9264; }
    { const char * tb_v9265 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9265; }
    { const char * tb_v9266 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9266; }
    { const char * tb_v9267 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9267; }
    { const char * tb_v9268 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9268; }
    { const char * tb_v9269 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9269; }
    { const char * tb_v9270 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9270; }
    { const char * tb_v9271 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9271; }
    { const char * tb_v9272 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9272; }
    { const char * tb_v9273 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9273; }
    { const char * tb_v9274 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9274; }
    { const char * tb_v9275 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9275; }
    { const char * tb_v9276 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9276; }
    { const char * tb_v9277 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9277; }
    { const char * tb_v9278 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9278; }
    { const char * tb_v9279 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v9279; }
    { const char * tb_v9280 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v9280; }
    { const char * tb_v9281 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9281; }
    { const char * tb_v9282 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v9282; }
    { const char * tb_v9283 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v9283; }
    { const char * tb_v9284 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9284; }
    { const char * tb_v9285 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9285; }
    { const char * tb_v9286 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v9286; }
    { const char * tb_v9287 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9287; }
    { const char * tb_v9288 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9288; }
    { const char * tb_v9289 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9289; }
    { const char * tb_v9290 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v9290; }
    { const char * tb_v9291 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v9291; }
    { const char * tb_v9292 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v9292; }
    { const char * tb_v9293 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9293; }
    { const char * tb_v9294 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9294; }
    { const char * tb_v9295 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9295; }
