    { const char * tb_v9432 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9432; }
    { const char * tb_v9433 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9433; }
    { const char * tb_v9434 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v9434; }
    { const char * tb_v9435 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9435; }
    { const char * tb_v9436 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9436; }
    { const char * tb_v9437 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9437; }
    { const char * tb_v9438 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9438; }
    { const char * tb_v9439 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v9439; }
    { const char * tb_v9440 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9440; }
    { const char * tb_v9441 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9441; }
    { const char * tb_v9442 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v9442; }
    { const char * tb_v9443 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9443; }
    { const char * tb_v9444 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v9444; }
    { const char * tb_v9445 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v9445; }
    { const char * tb_v9446 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9446; }
    { const char * tb_v9447 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v9447; }
    { const char * tb_v9448 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v9448; }
    { const char * tb_v9449 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v9449; }
    { const char * tb_v9450 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9450; }
    { const char * tb_v9451 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9451; }
    { const char * tb_v9452 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9452; }
    { const char * tb_v9453 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v9453; }
    { const char * tb_v9454 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v9454; }
    { const char * tb_v9455 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v9455; }
    { const char * tb_v9456 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v9456; }
    { const char * tb_v9457 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v9457; }
    { const char * tb_v9458 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v9458; }
    { const char * tb_v9459 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9459; }
    { const char * tb_v9460 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v9460; }
    { const char * tb_v9461 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9461; }
    { const char * tb_v9462 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v9462; }
    { const char * tb_v9463 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9463; }
    { const char * tb_v9464 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v9464; }
    { const char * tb_v9465 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9465; }
    { const char * tb_v9466 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9466; }
    { const char * tb_v9467 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v9467; }
    { const char * tb_v9468 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v9468; }
    { const char * tb_v9469 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v9469; }
    { const char * tb_v9470 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9470; }
    { const char * tb_v9471 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v9471; }
    { const char * tb_v9472 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v9472; }
    { const char * tb_v9473 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v9473; }
    { const char * tb_v9474 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v9474; }
    { const char * tb_v9475 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v9475; }
    { const char * tb_v9476 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v9476; }
    { const char * tb_v9477 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v9477; }
    { const char * tb_v9478 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v9478; }
    { const char * tb_v9479 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v9479; }
    { const char * tb_v9480 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v9480; }
    { const char * tb_v9481 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v9481; }
    { const char * tb_v9482 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v9482; }
    { const char * tb_v9483 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v9483; }
    { const char * tb_v9484 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v9484; }
    { const char * tb_v9485 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9485; }
    { const char * tb_v9486 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9486; }
    { const char * tb_v9487 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v9487; }
    { const char * tb_v9488 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v9488; }
    { const char * tb_v9489 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9489; }
    { const char * tb_v9490 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9490; }
    { const char * tb_v9491 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9491; }
    { const char * tb_v9492 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9492; }
    { const char * tb_v9493 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9493; }
    { const char * tb_v9494 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v9494; }
