    { const char * tb_v9496 = "    tb_meshes[tb_nmesh].tex = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9496; }
    { const char * tb_v9497 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9497; }
    { const char * tb_v9498 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9498; }
    { const char * tb_v9499 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9499; }
    { const char * tb_v9500 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9500; }
