    { const char * tb_v9503 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v9503; }
    { const char * tb_v9504 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9504; }
    { const char * tb_v9505 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v9505; }
    { const char * tb_v9506 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9506; }
    { const char * tb_v9507 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v9507; }
    { const char * tb_v9508 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9508; }
    { const char * tb_v9509 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v9509; }
    { const char * tb_v9510 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v9510; }
    { const char * tb_v9511 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9511; }
    { const char * tb_v9512 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9512; }
    { const char * tb_v9513 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9513; }
    { const char * tb_v9514 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9514; }
    { const char * tb_v9515 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9515; }
    { const char * tb_v9516 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9516; }
