    { const char * tb_v9520 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9520; }
    { const char * tb_v9521 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v9521; }
    { const char * tb_v9522 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9522; }
    { const char * tb_v9523 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9523; }
    { const char * tb_v9524 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9524; }
    { const char * tb_v9525 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9525; }
    { const char * tb_v9526 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9526; }
    { const char * tb_v9527 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9527; }
    { const char * tb_v9528 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9528; }
    { const char * tb_v9529 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v9529; }
    { const char * tb_v9530 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9530; }
    { const char * tb_v9531 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9531; }
    { const char * tb_v9532 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9532; }
    { const char * tb_v9533 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v9533; }
    { const char * tb_v9534 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v9534; }
    { const char * tb_v9535 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9535; }
    { const char * tb_v9536 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9536; }
    { const char * tb_v9537 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9537; }
    { const char * tb_v9538 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9538; }
    { const char * tb_v9539 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9539; }
    { const char * tb_v9540 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v9540; }
    { const char * tb_v9541 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9541; }
    { const char * tb_v9542 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9542; }
    { const char * tb_v9543 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v9543; }
    { const char * tb_v9544 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v9544; }
    { const char * tb_v9545 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9545; }
    { const char * tb_v9546 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9546; }
