    { const char * tb_v9551 = "        m->cap = m->cap ? m->cap * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9551; }
    { const char * tb_v9552 = "        m->t = (uint32_t *)realloc(m->t, sizeof(uint32_t) * 3 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v9552; }
    { const char * tb_v9553 = "        m->c = (uint32_t *)realloc(m->c, sizeof(uint32_t) * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v9553; }
    { const char * tb_v9554 = "        if (m->uv) m->uv = (double *)realloc(m->uv, sizeof(double) * 6 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v9554; }
