    { const char * tb_v9556 = "    if (m->uv) m->uv[6 * m->n] = __builtin_nan(\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v9556; }
    { const char * tb_v9557 = "    uint32_t *t = m->t + 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9557; }
    { const char * tb_v9558 = "    t[0] = tb_mesh_vertex(m, x1, y1, z1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9558; }
