    { const char * tb_v9597 = "// Всё в целых, одной формулой на процессоре и на видеокарте (tb3.vert, tb3.metal): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v9597; }
    { const char * tb_v9598 = "TB_API double tb_lt[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9598; }
    { const char * tb_v9599 = "TB_API int tb_lamb = -1;   // фон × 256; -1 — света нет, цвета как есть\n"; *(const char * *)tb_grow(v_lines) = tb_v9599; }
    { const char * tb_v9600 = "TB_API void tb_light(double dx, double dy, double dz, double amb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9600; }
