    { const char * tb_v9613 = "    if (m->nrmcap < m->n) { m->nrmcap = m->cap; m->nrm = (int32_t *)realloc(m->nrm, sizeof(int32_t) * 3 * (size_t)m->nrmcap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9613; }
