    { const char * tb_v9623 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v9623; }
    { const char * tb_v9624 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9624; }
    { const char * tb_v9625 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9625; }
    { const char * tb_v9626 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9626; }
    { const char * tb_v9627 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v9627; }
    { const char * tb_v9628 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9628; }
    { const char * tb_v9629 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v9629; }
    { const char * tb_v9630 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9630; }
