    { const char * tb_v9643 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v9643; }
    { const char * tb_v9644 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v9644; }
    { const char * tb_v9645 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9645; }
    { const char * tb_v9646 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v9646; }
    { const char * tb_v9647 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9647; }
