    { const char * tb_v9656 = "// ---- картинка на сетке: плоскости u·W и v·W по трём углам ----\n"; *(const char * *)tb_grow(v_lines) = tb_v9656; }
    { const char * tb_v9657 = "// треугольник t сетки рисуется картинкой? (есть картинка, у треугольника есть (u, v), видеокарта умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v9657; }
    { const char * tb_v9658 = "TB_INL int tb_tex_on(const tb_mesh *m, long long t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9658; }
