    { const char * tb_v9660 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9660; }
    { const char * tb_v9661 = "// (u, v) угла в 1/16 точки картинки, не дальше ±2^19 (чтобы плоскости влезли в 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v9661; }
    { const char * tb_v9662 = "TB_INL long long tb_tex_q(double u, int w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9662; }
    { const char * tb_v9663 = "    double q = u * w * 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v9663; }
    { const char * tb_v9664 = "    if (!(q > -524288)) q = -524288;   // и NaN\n"; *(const char * *)tb_grow(v_lines) = tb_v9664; }
