    { const char * tb_v9666 = "    return tb_rnd(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v9666; }
    { const char * tb_v9667 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9667; }
    { const char * tb_v9668 = "// плоскость S по трём углам в целых: та же формула, что у плоскости глубины в tb_m3_tri\n"; *(const char * *)tb_grow(v_lines) = tb_v9668; }
    { const char * tb_v9669 = "static void tb_tex_plane_i(const long long *a, const long long *b, const long long *c, const long long *S, int64_t *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9669; }
    { const char * tb_v9670 = "    long long s0 = S[0], s1 = S[1], s2 = S[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9670; }
    { const char * tb_v9671 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9671; }
    { const char * tb_v9672 = "    if (area < 0) { const long long *k = b; b = c; c = k; long long ks = s1; s1 = s2; s2 = ks; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9672; }
    { const char * tb_v9673 = "    if (area == 0) { o[0] = o[1] = 0; o[2] = 64 * s0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9673; }
    { const char * tb_v9674 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = s1 - s0, d2 = s2 - s0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9674; }
    { const char * tb_v9675 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v9675; }
    { const char * tb_v9676 = "    o[0] = A; o[1] = B; o[2] = 64 * s0 - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9676; }
    { const char * tb_v9677 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9677; }
    { const char * tb_v9678 = "// запись текстуры для углов (x, y, D) в целых и (u, v) углов треугольника t\n"; *(const char * *)tb_grow(v_lines) = tb_v9678; }
    { const char * tb_v9679 = "static void tb_tex_rec_i(const tb_mesh *m, long long t, const long long *a, const long long *b, const long long *c, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9679; }
    { const char * tb_v9680 = "    const tb_image *im = &tb_imgs[m->tex];\n"; *(const char * *)tb_grow(v_lines) = tb_v9680; }
    { const char * tb_v9681 = "    const double *q = m->uv + 6 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v9681; }
    { const char * tb_v9682 = "    const long long *p[3] = { a, b, c };\n"; *(const char * *)tb_grow(v_lines) = tb_v9682; }
    { const char * tb_v9683 = "    long long su[3], sv[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9683; }
