    { const char * tb_v9817 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v9817; }
    { const char * tb_v9818 = "                  : -(long long)(((unsigned long long)(-a) + (unsigned long long)b - 1) / (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9818; }
    { const char * tb_v9819 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9819; }
    { const char * tb_v9820 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v9820; }
    { const char * tb_v9821 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v9821; }
    { const char * tb_v9822 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v9822; }
    { const char * tb_v9823 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9823; }
    { const char * tb_v9824 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9824; }
    { const char * tb_v9825 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v9825; }
    { const char * tb_v9826 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9826; }
    { const char * tb_v9827 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9827; }
    { const char * tb_v9828 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v9828; }
    { const char * tb_v9829 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9829; }
    { const char * tb_v9830 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9830; }
    { const char * tb_v9831 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v9831; }
    { const char * tb_v9832 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v9832; }
    { const char * tb_v9833 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9833; }
    { const char * tb_v9834 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9834; }
    { const char * tb_v9835 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9835; }
    { const char * tb_v9836 = "    int ret = area > 0 ? 1 : 2;   // 1 — грань смотрит на нас, 2 — спиной\n"; *(const char * *)tb_grow(v_lines) = tb_v9836; }
    { const char * tb_v9837 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9837; }
    { const char * tb_v9838 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9838; }
    { const char * tb_v9839 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v9839; }
    { const char * tb_v9840 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9840; }
    { const char * tb_v9841 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v9841; }
    { const char * tb_v9842 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9842; }
    { const char * tb_v9843 = "    return ret;\n"; *(const char * *)tb_grow(v_lines) = tb_v9843; }
    { const char * tb_v9844 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9844; }
    { const char * tb_v9845 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v9845; }
    { const char * tb_v9846 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v9846; }
    { const char * tb_v9847 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v9847; }
    { const char * tb_v9848 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9848; }
    { const char * tb_v9849 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9849; }
    { const char * tb_v9850 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9850; }
    { const char * tb_v9851 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9851; }
    { const char * tb_v9852 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9852; }
    { const char * tb_v9853 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9853; }
    { const char * tb_v9854 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9854; }
    { const char * tb_v9855 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9855; }
    { const char * tb_v9856 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v9856; }
    { const char * tb_v9857 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9857; }
    { const char * tb_v9858 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9858; }
    { const char * tb_v9859 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v9859; }
    { const char * tb_v9860 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9860; }
    { const char * tb_v9861 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9861; }
    { const char * tb_v9862 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v9862; }
    { const char * tb_v9863 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9863; }
    { const char * tb_v9864 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9864; }
    { const char * tb_v9865 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9865; }
    { const char * tb_v9866 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9866; }
    { const char * tb_v9867 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v9867; }
    { const char * tb_v9868 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v9868; }
    { const char * tb_v9869 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9869; }
    { const char * tb_v9870 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9870; }
    { const char * tb_v9871 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v9871; }
    { const char * tb_v9872 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9872; }
    { const char * tb_v9873 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9873; }
    { const char * tb_v9874 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9874; }
    { const char * tb_v9875 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники по две строки:\n"; *(const char * *)tb_grow(v_lines) = tb_v9875; }
    { const char * tb_v9876 = "// (номера углов, цвет) и (нормаль × 2^14, -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v9876; }
    { const char * tb_v9877 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9877; }
    { const char * tb_v9878 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9878; }
    { const char * tb_v9879 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9879; }
    { const char * tb_v9880 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9880; }
    { const char * tb_v9881 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v9881; }
    { const char * tb_v9882 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9882; }
    { const char * tb_v9883 = "            tb_mesh_normals(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v9883; }
    { const char * tb_v9884 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9884; }
    { const char * tb_v9885 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9885; }
    { const char * tb_v9886 = "                int32_t *o = dst + 4 * (m->gt + 2 * t);\n"; *(const char * *)tb_grow(v_lines) = tb_v9886; }
    { const char * tb_v9887 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v9887; }
    { const char * tb_v9888 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v9888; }
    { const char * tb_v9889 = "                for (int k = 0; k < 3; k++) o[4 + k] = m->nrm[3 * t + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9889; }
    { const char * tb_v9890 = "                o[7] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9890; }
    { const char * tb_v9891 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9891; }
    { const char * tb_v9892 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9892; }
    { const char * tb_v9893 = "        at += m->nv + 2 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9893; }
    { const char * tb_v9894 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9894; }
    { const char * tb_v9895 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v9895; }
    { const char * tb_v9896 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9896; }
    { const char * tb_v9897 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9897; }
    { const char * tb_v9898 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v9898; }
    { const char * tb_v9899 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v9899; }
    { const char * tb_v9900 = "    pc->tbase = (int32_t)(m->gt + 2 * g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v9900; }
    { const char * tb_v9901 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9901; }
    { const char * tb_v9902 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9902; }
    { const char * tb_v9903 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v9903; }
    { const char * tb_v9904 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9904; }
    { const char * tb_v9905 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v9905; }
    { const char * tb_v9906 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v9906; }
    { const char * tb_v9907 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9907; }
    { const char * tb_v9908 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v9908; }
    { const char * tb_v9909 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9909; }
    { const char * tb_v9910 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9910; }
    { const char * tb_v9911 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v9911; }
    { const char * tb_v9912 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9912; }
    { const char * tb_v9913 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9913; }
    { const char * tb_v9914 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v9914; }
    { const char * tb_v9915 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v9915; }
    { const char * tb_v9916 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v9916; }
    { const char * tb_v9917 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v9917; }
    { const char * tb_v9918 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9918; }
    { const char * tb_v9919 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9919; }
    { const char * tb_v9920 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v9920; }
    { const char * tb_v9921 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v9921; }
    { const char * tb_v9922 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v9922; }
    { const char * tb_v9923 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9923; }
    { const char * tb_v9924 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9924; }
    { const char * tb_v9925 = "    int texm = m->tex >= 0 && m->uv && (!tb_gpu_on || tb_gpu_tex);   // сетка с картинкой: углы считает процессор\n"; *(const char * *)tb_grow(v_lines) = tb_v9925; }
    { const char * tb_v9926 = "    if (tb_gpu_on && tb_gpu_mesh && !texm) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v9926; }
    { const char * tb_v9927 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v9927; }
    { const char * tb_v9928 = "        if (go->rbatch != tb_gbatch) {   // запись этого вызова ещё не в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v9928; }
    { const char * tb_v9929 = "            go->ri = tb_grn++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9929; }
    { const char * tb_v9930 = "            go->rbatch = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v9930; }
    { const char * tb_v9931 = "            tb_grec_p[tb_gslot * TB_GR_CAP + go->ri] = go->rec;\n"; *(const char * *)tb_grow(v_lines) = tb_v9931; }
    { const char * tb_v9932 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9932; }
    { const char * tb_v9933 = "        tb_ginst *g = tb_gin ? &tb_gi[tb_gin - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9933; }
    { const char * tb_v9934 = "        if (g && g->m == 3u && g->x0 == (int32_t)go->id && g->y0 == go->cull && g->ox == t0 && g->oy == tn &&\n"; *(const char * *)tb_grow(v_lines) = tb_v9934; }
    { const char * tb_v9935 = "            g->x1 + g->y1 == go->ri && (long long)(g->y1 + 1) * tn < 2000000000) g->y1++;   // та же сетка подряд: одним вызовом\n"; *(const char * *)tb_grow(v_lines) = tb_v9935; }
    { const char * tb_v9936 = "        else tb_gpu_add(go->id, go->cull, go->ri, 1, t0, tn, 0, 3u);\n"; *(const char * *)tb_grow(v_lines) = tb_v9936; }
