    { const char * tb_v10253 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10253; }
    { const char * tb_v10254 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v10254; }
    { const char * tb_v10255 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10255; }
