    { const char * tb_v10300 = "    pthread_mutex_unlock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v10300; }
    { const char * tb_v10301 = "    // общая громкость (плавно) и ограничитель: громко — сразу тише, потом медленно назад\n"; *(const char * *)tb_grow(v_lines) = tb_v10301; }
