    { const char * tb_v10319 = "// без устройства: время идёт как настоящее, звук — в файл (TB_SOUND_FILE) или никуда\n"; *(const char * *)tb_grow(v_lines) = tb_v10319; }
    { const char * tb_v10320 = "static void tb_snd_paced(FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10320; }
    { const char * tb_v10321 = "    float buf[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10321; }
