    { const char * tb_v10323 = "    unsigned long long bytes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10323; }
    { const char * tb_v10324 = "    long long next = tb_snd_now_us();\n"; *(const char * *)tb_grow(v_lines) = tb_v10324; }
    { const char * tb_v10325 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10325; }
