    { const char * tb_v10327 = "        if (f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10327; }
    { const char * tb_v10328 = "            for (int i = 0; i < TB_SBLOCK * 2; i++) pcm[i] = (short)lrintf(buf[i] * 32767);\n"; *(const char * *)tb_grow(v_lines) = tb_v10328; }
