    { const char * tb_v10330 = "            bytes += sizeof pcm;\n"; *(const char * *)tb_grow(v_lines) = tb_v10330; }
    { const char * tb_v10331 = "            // заголовок WAV сразу верный: программа может закончиться когда угодно\n"; *(const char * *)tb_grow(v_lines) = tb_v10331; }
    { const char * tb_v10332 = "            unsigned int riff = (unsigned int)(36 + bytes), data = (unsigned int)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v10332; }
