    { const char * tb_v10508 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10508; }
    { const char * tb_v10509 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10509; }
    { const char * tb_v10510 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10510; }
    { const char * tb_v10511 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10511; }
    { const char * tb_v10512 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v10512; }
    { const char * tb_v10513 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10513; }
    { const char * tb_v10514 = "        uint32_t n = tb_le32(b + p + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v10514; }
    { const char * tb_v10515 = "        const unsigned char *c = b + p + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v10515; }
    { const char * tb_v10516 = "        if ((long)n > sz - p - 8) n = (uint32_t)(sz - p - 8);   // последний кусок обрезан — берём что есть\n"; *(const char * *)tb_grow(v_lines) = tb_v10516; }
    { const char * tb_v10517 = "        if (memcmp(b + p, \"fmt \", 4) == 0 && n >= 16) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10517; }
    { const char * tb_v10518 = "            tag = tb_le16(c); ch = tb_le16(c + 2); rate = tb_le32(c + 4); bits = tb_le16(c + 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v10518; }
    { const char * tb_v10519 = "            if (tag == 0xFFFE && n >= 26) tag = tb_le16(c + 24);   // «расширенный» WAV: вид внутри\n"; *(const char * *)tb_grow(v_lines) = tb_v10519; }
    { const char * tb_v10520 = "        } else if (memcmp(b + p, \"data\", 4) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10520; }
