    { const char * tb_v10523 = "        p += 8 + (long)n + (n & 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10523; }
    { const char * tb_v10524 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10524; }
    { const char * tb_v10525 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v10525; }
    { const char * tb_v10526 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10526; }
    { const char * tb_v10527 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v10527; }
    { const char * tb_v10528 = "        tb_err = !data ? \"в WAV нет звука (нет куска data)\" : \"такой WAV не умею: нужен PCM 8/16/24/32 бита или float\";\n"; *(const char * *)tb_grow(v_lines) = tb_v10528; }
    { const char * tb_v10529 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10529; }
    { const char * tb_v10530 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10530; }
