    { const char * tb_v10598 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10598; }
    { const char * tb_v10599 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v10599; }
    { const char * tb_v10600 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10600; }
    { const char * tb_v10601 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10601; }
    { const char * tb_v10602 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10602; }
