    { const char * tb_v10604 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v10604; }
    { const char * tb_v10605 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v10605; }
    { const char * tb_v10606 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10606; }
    { const char * tb_v10607 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10607; }
